def word_count(text):
    """Count the words in text."""
    return len(text.split())

files.test_text_tools.py:
import unittest

from text_tools import slugify, word_count


class TextToolsTests(unittest.TestCase):
    def test_word_count(self):
        self.assertEqual(word_count("one two three"), 3)

    def test_slugify_punctuation(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_slugify_runs_and_ends(self):
        self.assertEqual(slugify("  --Local LLM   Harness v2--  "), "local-llm-harness-v2")


if __name__ == "__main__":
    unittest.main()

