DEFAULTS = {
    "retries": 3,
    "timeout_seconds": 30,
}


def setting(name, overrides=None):
    """Return a setting, preferring an override when one is given."""
    return (overrides or {}).get(name, DEFAULTS[name])

files.test_app_settings.py:
import unittest

from app_settings import setting


class SettingTests(unittest.TestCase):
    def test_default_timeout(self):
        self.assertEqual(setting("timeout_seconds"), 30)

    def test_override(self):
        self.assertEqual(setting("retries", {"retries": 5}), 5)


if __name__ == "__main__":
    unittest.main()
